from threetears.evals import Eval

from label import label

def print_label(case):
    """The nutrition label the spec sheet gets."""
    return {"label": label(case)}


def as_approved(case, out):
    """The label is the signed-off text."""
    return out["label"] == case["approved"]

sheets = Eval("data/approved.jsonl", runner=print_label, grader=[as_approved], k=1)
